import{c as r,Z as e,Q as s,j as l,m as n,o}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"水调歌头·明月几时有","description":"","frontmatter":{"title":"水调歌头·明月几时有","author":"苏轼","dynasty":"宋"},"headers":[],"relativePath":"books/shici/songci/1.md","filePath":"books/shici/songci/1.md"}'),h={name:"books/shici/songci/1.md"};function c(p,a,d,u,_,m){const t=e("PoemAuthor"),i=e("PoemNav");return s(),l("div",null,[a[0]||(a[0]=n('<h1 id="水调歌头·明月几时有" tabindex="-1">水调歌头·明月几时有 <a class="header-anchor" href="#水调歌头·明月几时有" aria-label="Permalink to &quot;水调歌头·明月几时有&quot;">​</a></h1><p><strong>[宋] <a href="/authors/sushi.html">苏轼</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>明月几时有？把酒问青天。不知天上宫阙，今夕是何年。我欲乘风归去，又恐琼楼玉宇，高处不胜寒。起舞弄清影，何似在人间。</p><p>转朱阁，低绮户，照无眠。不应有恨，何事长向别时圆？人有悲欢离合，月有阴晴圆缺，此事古难全。但愿人长久，千里共婵娟。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>把酒：端起酒杯</li><li>宫阙：宫殿</li><li>琼楼玉宇：美玉砌成的楼阁，指月中宫殿</li><li>不胜：承受不住</li><li>朱阁：朱红色的楼阁</li><li>绮户：雕花的窗户</li><li>婵娟：美好的月光，形容月色美好</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>明月从什么时候才开始出现的？我端起酒杯遥问苍天。不知道在天上的宫殿，今天晚上是哪一年。我想要乘御清风回到天上，又恐怕在美玉砌成的楼宇，受不住高耸九天的寒冷。翩翩起舞玩赏着月下清影，哪像是在人间。</p><p>月儿转过朱红色的楼阁，低低地挂在雕花的窗户上，照着没有睡意的人。明月不该对人们有什么怨恨吧，为什么偏在人们离别时才圆呢？人有悲欢离合的变迁，月有阴晴圆缺的转换，这种事自古来难以周全。只希望这世上所有人的亲人能平安健康，即便相隔千里，也能共享这美好的月光。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首词是中秋望月怀人之作，表达了对胞弟苏辙的无限思念。词人运用形象的描绘和浪漫主义的想象，紧紧围绕中秋之月展开描写、抒情和议论，从天上与人间、月与人、空间与时间这些相联系的范畴进行思考，把人世间的悲欢离合之情纳入对宇宙人生的哲理性追寻之中。</p><p>上片写望月，词人把酒问天，流露出对宇宙和人生的疑惑，以及对天上仙境的向往与对人间生活的眷恋之间的矛盾心理。下片写怀人，由月圆人不圆的感慨，引出对人生的深刻思考，最终以豁达的祝福作结。</p><p>&quot;但愿人长久，千里共婵娟&quot;一句，表达了旷达的胸怀和美好的祝愿，成为中秋望月怀人时最常被引用的名句。全词意境豪放而阔大，情怀乐观而旷达，对明月的向往之情，对人间的眷恋之意，对亲人的美好祝福，都流淌在字里行间。</p>',14)),o(t,{name:"苏轼",years:"1037年－1101年",desc:"字子瞻，号东坡居士，北宋著名文学家、书法家、画家，唐宋八大家之一。其词开豪放一派，与辛弃疾并称“苏辛”。",link:"/authors/sushi"}),o(i)])}const P=r(h,[["render",c]]);export{b as __pageData,P as default};
